// Generated by philote from page /horses/[id]/edit. PageBody's body is written by
// a model and pinned in philote.lock (decision-2).
/* eslint-disable @typescript-eslint/no-unused-vars -- every page gets the same imports */
import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { Suspense } from "react";

import * as Icons from "lucide-react";

import { horses } from "@/lib/api";
import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";

import { submit } from "./actions";
import Form from "./form";

export const metadata: Metadata = { title: "Edit Horse" };

export default function Page({ params }: PageProps<"/horses/[id]/edit">) {
    return (
        <main className="flex flex-1 flex-col">
            <PageBody
                title={"Edit Horse"}
                content={(className) => (
                    <div className={className}>
                        <Suspense fallback={<p className="text-muted-foreground">Loading…</p>}>
                            <Loaded params={params} />
                        </Suspense>
                    </div>
                )}
            />
        </main>
    );
}

// Loaded fills the form once its record and choices are in.
async function Loaded({ params }: Pick<PageProps<"/horses/[id]/edit">, "params">) {
    await connection();
    const { id } = await params;
    const result = await horses.get(id);
    if (!result.ok) {
        notFound();
    }
    const record = result.value;
    const options = {};
    const initial = {
        name: record.name,
        breed: record.breed,
        age: String(record.age),
        bio: record.bio,
    };
    return <Form action={submit.bind(null, id)} initial={initial} options={options} />;
}

type PageBodyProps = {
    title: string;
    content: (className: string) => React.ReactNode;
};

function PageBody({ title, content }: PageBodyProps): React.ReactNode {
    return (
      <div className="mx-auto flex w-full max-w-2xl flex-col gap-6 px-4 py-8 sm:px-6 sm:py-12">
        <header className="flex flex-col gap-3">
          <Badge variant="secondary" className="w-fit gap-1.5 rounded-xl">
            <Icons.Heart className="size-4" />
            Horse
          </Badge>
          <h1 className="font-heading text-3xl font-bold tracking-tight text-foreground sm:text-4xl">
            {title}
          </h1>
          <p className="text-base text-muted-foreground">
            Update this horse&apos;s details and save your changes.
          </p>
        </header>
        <Separator orientation="horizontal" />
        {content(
          "flex w-full flex-col gap-5 rounded-xl border bg-card p-5 text-card-foreground shadow-sm sm:p-8"
        )}
      </div>
    );
}
